constexpr int kCount = static_cast<int>(sizeof(kTable) / sizeof(kTable[0]));

/* Sorted; null means "not a known machine output" and the caller
 * shows the timer without a name. */
inline const Entry* Find(int id) {
    int lo = 0;
    int hi = kCount - 1;
    while (lo <= hi) {
        const int mid = (lo + hi) / 2;
        if (kTable[mid].id == id) {
            return &kTable[mid];
        }
        if (kTable[mid].id < id) {
            lo = mid + 1;
        }
        else {
            hi = mid - 1;
        }
    }
    return nullptr;
}

